const body = ($input.first().json && $input.first().json.body) || {};
const text = (body.text || '').toString().trim();
if (!text) throw new Error('Missing body.text (recognized speech from the companion app)');
if (text.length > 2000) throw new Error('text too long (>2000 chars)');
// voice is a Microsoft Edge / OpenAI-compatible voice name, not an ElevenLabs id
const voice = (body.voice || 'onyx').toString().trim();
return [{ json: { text, voice } }];

const raw = $json && $json.content && $json.content[0] && $json.content[0].text;
if (!raw || !raw.trim()) throw new Error('LLM returned empty reply');
return [{ json: { reply: raw.trim(), voice: $('Validate Input').item.json.voice } }];
